      n = labels[i];
      var screenR = n.r * k;
      var must = n === anchor;
      // Always name the biggest hubs so there is something to navigate by.
      if (!must && i >= 14 && screenR < (focused ? 3.2 : 6.4)) continue;
      var sx = n.x * k, sy = n.y * k + screenR + 4;
      var label = n.title.length > 34 ? n.title.slice(0, 33) + '…' : n.title;
      var halfW = Math.min(110, label.length * 3.3) + 6;
      var row = Math.round(sy / 15), c0 = Math.floor((sx - halfW) / 24), c1 = Math.floor((sx + halfW) / 24);
      var free = true, c;
      for (c = c0; c <= c1; c++) if (taken[row + ':' + c] || taken[(row - 1) + ':' + c]) { free = false; break; }
      if (!free && !must) continue;
      for (c = c0; c <= c1; c++) taken[row + ':' + c] = 1;
      ctx.fillStyle = rgba(text, n === anchor ? 1 : 0.82);
      ctx.fillText(label, n.x, n.y + n.r + 4 / k);
